"""Feature gate dictionary combiner."""
from typing import Dict, Any, List

def combine_gate_dicts(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """
    Combines gate dictionaries following Rule H12:
    - Nested dictionaries are merged recursively.
    - List values are concatenated and deduplicated (first-seen order preserved).
    - Other conflicting types are replaced by the override value.
    """
    res = dict(base)
    for k, v in override.items():
        if k in res:
            if isinstance(res[k], dict) and isinstance(v, dict):
                # Rule H12: nested dictionaries are merged recursively
                res[k] = combine_gate_dicts(res[k], v)
            elif isinstance(res[k], list) and isinstance(v, list):
                # Rule H12: list values must be concatenated with deduplication (first-seen order)
                combined_list = res[k] + v
                deduplicated_list = []
                seen = set()
                for item in combined_list:
                    if item not in seen:
                        deduplicated_list.append(item)
                        seen.add(item)
                res[k] = deduplicated_list
            else:
                # Rule H12 implies other types (or non-matching types) are replaced
                res[k] = v
        else:
            # Key not in base, just add it from override
            res[k] = v
    return res

def is_valid_gate_key(key: str) -> bool:
    return bool(key and isinstance(key, str))
